static bool trans_jal(DisasContext *ctx, arg_j *a)
{
    tcg_gen_movi_i64(dest(a->rd), bwm_word64(ctx->pc + 4, 0));
    gen_goto_tb(ctx, 0, ctx->pc + 4 * (int64_t)a->imm);
    return true;
}

static bool trans_jalr(DisasContext *ctx, arg_i *a)
{
    TCGv_i64 t = tcg_temp_new_i64();
    TCGv_i64 low = tcg_temp_new_i64();
    TCGLabel *aligned = gen_new_label();
    gen_helper_machine_ea(t, reg(a->ra), tcg_constant_i64(a->imm));
    tcg_gen_andi_i64(low, t, 3);
    tcg_gen_brcondi_i64(TCG_COND_EQ, low, 0, aligned);
    tcg_gen_movi_i64(cpu_pc, ctx->pc);
    gen_helper_fault(tcg_env);
    gen_set_label(aligned);
    tcg_gen_movi_i64(dest(a->rd), bwm_word64(ctx->pc + 4, 0));
    tcg_gen_mov_i64(cpu_pc, t);
    tcg_gen_lookup_and_goto_ptr();
    ctx->base.is_jmp = DISAS_NORETURN;
    return true;
}

static void bwm_tr_init_disas_context(DisasContextBase *db, CPUState *cs)
{
}

static void bwm_tr_tb_start(DisasContextBase *db, CPUState *cs)
{
}

static void bwm_tr_insn_start(DisasContextBase *db, CPUState *cs)
{
    tcg_gen_insn_start(db->pc_next);
}

static void bwm_tr_translate_insn(DisasContextBase *db, CPUState *cs)
{
    DisasContext *ctx = container_of(db, DisasContext, base);
    uint32_t insn;

    ctx->pc = db->pc_next;
    insn = translator_ldl(cpu_env(cs), db, ctx->pc);
    db->pc_next = ctx->pc + 4;
    if (!decode_insn(ctx, insn)) {
        tcg_gen_movi_i64(cpu_pc, ctx->pc);
        gen_helper_fault(tcg_env);
        db->is_jmp = DISAS_NORETURN;
    }
    if (db->is_jmp == DISAS_NEXT && (db->pc_next & ~TARGET_PAGE_MASK) == 0) {
        db->is_jmp = DISAS_TOO_MANY;
    }
}

static void bwm_tr_tb_stop(DisasContextBase *db, CPUState *cs)
{
    DisasContext *ctx = container_of(db, DisasContext, base);

    switch (db->is_jmp) {
    case DISAS_NORETURN:
        break;
    case DISAS_NEXT:
    case DISAS_TOO_MANY:
        gen_goto_tb(ctx, 0, db->pc_next);
        break;
    default:
        g_assert_not_reached();
    }
}

static const TranslatorOps bwm_tr_ops = {
    .init_disas_context = bwm_tr_init_disas_context,
    .tb_start = bwm_tr_tb_start,
    .insn_start = bwm_tr_insn_start,
    .translate_insn = bwm_tr_translate_insn,
    .tb_stop = bwm_tr_tb_stop,
};

void bwm_translate_code(CPUState *cs, TranslationBlock *tb, int *max_insns,
                        vaddr pc, void *host_pc)
{
    DisasContext dc = { };

    translator_loop(cs, tb, max_insns, pc, host_pc, &bwm_tr_ops, &dc.base);
}
